from pathlib import Path
import pandas as pd
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, HRFlowable, KeepTogether

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'research-data'/'processed'
OUT=ROOT/'public'/'reports'/'SupeRR_Pressure_Methodology_Report.pdf'
OUT.parent.mkdir(parents=True,exist_ok=True)
bat=pd.read_csv(DATA/'top10_batter_evidence.csv').sort_values('final_rank')
bowl=pd.read_csv(DATA/'top10_bowler_evidence.csv').sort_values('final_rank')

# Conventional report typography: serif text, restrained sans-serif headings.
font_files={
 'ReportSerif':'/usr/share/fonts/truetype/liberation/LiberationSerif-Regular.ttf',
 'ReportSerifBold':'/usr/share/fonts/truetype/liberation/LiberationSerif-Bold.ttf',
 'ReportSerifItalic':'/usr/share/fonts/truetype/liberation/LiberationSerif-Italic.ttf',
 'ReportSans':'/usr/share/fonts/truetype/lato/Lato-Regular.ttf',
 'ReportSansBold':'/usr/share/fonts/truetype/lato/Lato-Bold.ttf'}
for n,f in font_files.items():
 if Path(f).exists(): pdfmetrics.registerFont(TTFont(n,f))

S=getSampleStyleSheet()
S.add(ParagraphStyle(name='TitleR',fontName='ReportSansBold',fontSize=23,leading=28,textColor=colors.black,spaceAfter=8))
S.add(ParagraphStyle(name='SubR',fontName='ReportSerif',fontSize=13,leading=18,textColor=colors.HexColor('#333333'),spaceAfter=12))
S.add(ParagraphStyle(name='KickerR',fontName='ReportSansBold',fontSize=8,leading=10,textColor=colors.HexColor('#555555'),spaceAfter=8))
S.add(ParagraphStyle(name='H1R',fontName='ReportSansBold',fontSize=15,leading=19,textColor=colors.black,spaceBefore=11,spaceAfter=7,keepWithNext=True))
S.add(ParagraphStyle(name='H2R',fontName='ReportSansBold',fontSize=10.5,leading=14,textColor=colors.black,spaceBefore=8,spaceAfter=4,keepWithNext=True))
S.add(ParagraphStyle(name='BodyR',fontName='ReportSerif',fontSize=10.1,leading=14.1,textColor=colors.HexColor('#202020'),spaceAfter=6))
S.add(ParagraphStyle(name='SmallR',fontName='ReportSerif',fontSize=9,leading=12,textColor=colors.HexColor('#292929'),spaceAfter=5))
S.add(ParagraphStyle(name='CellR',fontName='ReportSans',fontSize=7.4,leading=9,textColor=colors.black))
S.add(ParagraphStyle(name='HeadR',fontName='ReportSansBold',fontSize=7.2,leading=9,textColor=colors.black))
S.add(ParagraphStyle(name='CaptionR',fontName='ReportSans',fontSize=7.4,leading=9,textColor=colors.HexColor('#555555'),spaceBefore=3,spaceAfter=7))

def P(t,st='BodyR'): return Paragraph(str(t),S[st])
def N(v,d=1): return '—' if pd.isna(v) else f'{float(v):,.{d}f}'
def I(v): return '—' if pd.isna(v) else f'{int(round(float(v))):,}'
def table(rows,widths):
 t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([
 ('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),
 ('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),
 ('LINEBELOW',(0,0),(-1,0),0.8,colors.black),('LINEBELOW',(0,1),(-1,-1),0.25,colors.HexColor('#B7B7B7'))]))
 return t
story=[]
# Cover page
story += [Spacer(1,28*mm),P('SUPERR SELECTOR SEASON 2  /  ROUND 1','KickerR'),P('Methodology report','TitleR'),P('Pressure-performance analysis of batters and bowlers in IPL and T20 International cricket','SubR'),HRFlowable(width='100%',thickness=.7,color=colors.black,spaceBefore=3,spaceAfter=16),P('<b>Prepared by</b><br/>Faaiz Qureshi'),P('<b>Submission date</b><br/>17 November 2026'),P('<b>Data scope</b><br/>IPL 2022–2026 and T20 International matches in the supplied dataset'),Spacer(1,13*mm),P('This report documents the problem addressed, the pressure definition, the data preparation, the batting and bowling calculations, the eligibility rules, the cross-format ranking procedure and the checks applied to the final results.'),PageBreak()]
# Problem and pressure
story += [P('1. Problem statement','H1R'),P('Round 1 asks for a data-driven system that measures how batters and bowlers perform in high-pressure match situations compared with their usual performance. The required outputs are two ordered lists: the ten best-performing batters under pressure and the ten best-performing bowlers under pressure.'),P('The problem statement leaves the definition of pressure and the choice of analytical method to the participant. The report must therefore explain which match situations are treated as pressure, how performance is measured, how comparisons are made fairly, and how the final rankings are supported by evidence.'),P('The purpose of this analysis is to rank historical pressure performance in the supplied dataset. It does not recommend players for Rajasthan Royals to retain, acquire or select at auction.'),P('2. Pressure definition','H1R'),P('The pressure label is assigned using the state of the innings immediately before a delivery. For batting, a delivery is classified as pressure if either of the following conditions is true:'),P('<b>Death phase:</b> at least 75% of the scheduled legal balls in the innings have elapsed. In a standard 20-over innings this corresponds to overs 16–20.'),P('<b>Batting-resource pressure:</b> five or more wickets have already fallen before the delivery.'),P('The two conditions are combined as a union. A delivery meeting both conditions is counted once. The union captures late-innings time pressure and the reduced batting resources associated with a substantial loss of wickets.'),P('For bowling, the evaluated pressure phase is the death phase: at least 75% of scheduled legal balls have elapsed. Bowling measures focus on wicket-taking and a limited known-boundary-event control measure during this phase.'),P('The supplied data did not support a sufficiently reliable reconstruction of exact required run rate, target pressure or score margin. Those variables were not used. The pressure label is an operational definition based on available pre-delivery match state; it is not intended to represent every possible form of pressure in cricket.'),P('3. Dataset and scope','H1R'),P('The source pack contains ball-by-ball match records and supporting competition, team, player, match and playing-XI information. The primary comparison includes IPL seasons 2022 to 2026 and T20 International matches in the supplied period. Other domestic T20 competitions are excluded from the IPL comparison.'),P('The final analysis contains 828 matches: 364 IPL matches and 464 T20I matches. After the stated match and innings filters, 193,372 eligible delivery rows remain, including 57,330 deliveries labelled as batting pressure. IPL and T20I are retained as separate formats throughout the scoring process.'),P('4. Data preparation','H1R'),P('Delivery records were cleaned and standardised. Match and innings state was reconstructed in delivery order so that the pressure label uses information available before the delivery outcome. Player-match observations were then built separately for batting and bowling.'),P('Batting records retain pressure balls, batter runs, dismissals and boundary-ball events. Bowling records retain legal death balls, bowler-credited wickets and known boundary events. Match-level observations are preserved for consistency calculations.'),P('The format-specific outputs were checked for duplicate player-format keys. Player identity across formats was joined using the canonical identity mapping in the supplied data. The identity bridge is retained in the project files for audit.'),PageBreak()]
# Batting model
story += [P('5. Batting model','H1R'),P('The batting score contains four dimensions. The baseline assigns 25% to each dimension. Metrics are converted to peer-group percentiles within format and observed batting role, so that players are compared with broadly similar batting responsibilities.'),P('5.1 Pressure output','H2R'),P('Pressure output is a weighted combination of pressure strike rate and boundary-ball rate:'),P('<b>Pressure strike rate</b> = 100 × batter runs in pressure deliveries ÷ pressure balls faced.'),P('<b>Boundary-ball rate</b> = 100 × pressure balls producing a four or six ÷ pressure balls faced.'),P('<b>Output score</b> = 0.70 × pressure strike-rate percentile + 0.30 × boundary-ball-rate percentile.'),P('Observed batting positions are grouped into 1–2 (opening), 3–4 (top order), 5–7 (middle order) and 8–11 (lower order). Extended 12+ positions are retained descriptively but are not treated as a standard peer cohort. Role-level scores are combined using pressure-ball exposure as the weight. At least 80% scoreable role coverage is required.'),P('5.2 Adaptability','H2R'),P('Adaptability measures the difference between pressure and normal-context strike rate after role and format adjustment. The percentile of this pressure-minus-normal difference is used as the adaptability component. It indicates whether a player maintains or improves scoring rate in the defined pressure context; it is not interpreted as a causal effect of pressure.'),P('5.3 Dismissal-risk control','H2R'),P('Dismissal risk is estimated using an empirical-Bayes probability per pressure ball. The estimate is shrunk towards a population prior so that small samples do not produce extreme rates solely because of a small number of dismissals. The component is inverted for scoring: a lower estimated dismissal probability receives a higher percentile.'),P('5.4 Match consistency','H2R'),P('Consistency is calculated from the interquartile range (IQR) of match-level pressure strike rates. A match enters this calculation only if the batter faced at least five pressure balls in that match. A lower IQR indicates less match-to-match variation and receives a higher consistency percentile.'),P('5.5 Batting eligibility','H2R'),P('A batter must have at least 60 pressure balls, pressure observations in at least five matches, at least five qualifying matches for the consistency calculation, a normal-context baseline and at least 80% scoreable role coverage. Eligibility is tested separately in IPL and T20I. A player enters the combined final list only when eligible in both formats.'),P('Five batting weight configurations are tested: equal dimensions (25% each); output-led (40% output, 20% each for the other dimensions); adaptability-led (40% adaptability, 25% output, 20% risk control and 15% consistency); risk-control-led (40% risk control, 25% output, 20% adaptability and 15% consistency); and consistency-led (40% consistency, 25% output, 20% adaptability and 15% risk control). The final pool contains 13 batters eligible in both formats.'),P('6. Bowling model','H1R'),P('The bowling score focuses on death-phase performance. Effectiveness contributes 65% and match consistency contributes 35%. Bowlers are benchmarked separately by Pace/Spin style and format.'),P('6.1 Death-phase effectiveness','H2R'),P('<b>Death wicket rate</b> = 100 × bowler-credited wickets in death phase ÷ legal death balls bowled.'),P('<b>Effectiveness score</b> = 0.85 × adjusted death wicket-rate percentile + 0.15 × known-boundary-event control percentile.'),P('The known-boundary measure uses boundary events that can be identified reliably from the supplied batter-run-credit categories. It is not official economy rate, total runs conceded or complete dot-ball percentage. It is deliberately a smaller part of effectiveness. Three bowling weight configurations are tested: balanced reference (65% effectiveness / 35% consistency), wicket-threat-led (80% / 20%) and consistency-led (50% / 50%).'),P('6.2 Match consistency','H2R'),P('Consistency is calculated from the IQR of match-level death wicket rates. A match qualifies only when the bowler has at least six legal death balls in that match. A lower IQR receives a higher consistency percentile.'),P('6.3 Bowling eligibility','H2R'),P('A bowler must have at least 36 legal death balls, death-phase observations in at least five matches, at least five qualifying matches for the consistency calculation and a non-death baseline. Eligibility is tested independently in IPL and T20I. Only players eligible in both formats enter the combined final list.'),P('The final pool contains 62 bowlers eligible in both formats.'),PageBreak()]
# Reliability and aggregation
story += [P('7. Reliability and sample support','H1R'),P('Eligibility thresholds prevent very small samples from entering the final comparison. After eligibility, evidence tiers describe the amount of observed exposure and match coverage. For batters, pressure balls and pressure matches are used; for bowlers, legal death balls and death-phase matches are used.'),P('Empirical-Bayes estimates are used for dismissal and wicket probabilities to reduce instability from limited samples. Match-cluster bootstrap intervals are retained as supplementary uncertainty evidence. These intervals do not remove all uncertainty and are not themselves a component of the final score.'),P('A larger evidence tier indicates more observed exposure, not a guarantee that a player will repeat the same performance. Where a player has an uneven IPL and T20I sample, the format-specific counts should be considered alongside the combined rank.'),P('8. Cross-format ranking','H1R'),P('Batters are benchmarked by observed batting-order band and format. Bowlers are benchmarked by Pace/Spin and format. Competition-season reference rates are used when the environment cohort contains at least 120 pressure balls or legal death balls, 10 distinct players and three matches. Otherwise the broader format-and-role reference is used. The adjustment is: adjusted rate = player raw rate × leave-one-player-out format-role reference rate ÷ leave-one-player-out environment-role reference rate. The player’s own exposure is removed from both peer references to avoid self-influence. Raw and adjusted values are retained. This is a comparison adjustment, not a causal correction.'),P('Percentile scores are calculated within format and relevant peer group. Raw IPL and T20I rates are not directly added together. Three cross-format blends are tested:'),P('<b>Equal blend:</b> 50% IPL and 50% T20I.<br/><b>IPL-priority blend:</b> 70% IPL and 30% T20I.<br/><b>Exposure-weighted blend:</b> square-root exposure weights, capped so that neither format contributes less than 30% or more than 70%.'),P('Batting uses five dimension-weight configurations crossed with the three format blends, producing 15 scenarios. Bowling uses three dimension-weight configurations crossed with the same three format blends, producing nine scenarios.'),P('For each player, the final rank is the arithmetic mean of the ranks across the tested scenarios. The final list is ordered by this mean rank. Top-ten stability is calculated as:'),P('<b>Top-ten stability (%)</b> = 100 × number of scenarios in which the player ranks in the top ten ÷ total scenarios.'),P('This is a sensitivity measure. It describes how often the player remains in the top ten under the tested assumptions; it is not a probability of future performance.'),P('9. Final batter rankings','H1R'),P('Pressure strike rate is runs per 100 pressure balls. The figures in parentheses show the number of pressure balls in that format.' ,'SmallR')]
rows=[[P('Rank','HeadR'),P('Player','HeadR'),P('IPL pressure SR<br/>(balls)','HeadR'),P('T20I pressure SR<br/>(balls)','HeadR'),P('Top-ten stability','HeadR')]]
for _,r in bat.iterrows():
 rows.append([P(int(r.final_rank),'CellR'),P(r.striker_canonical_name,'CellR'),P(f"{N(r.IPL_pressure_sr)} ({I(r.IPL_pressure_balls)})",'CellR'),P(f"{N(r.T20I_pressure_sr)} ({I(r.T20I_pressure_balls)})",'CellR'),P(f"{N(r.top10_robustness_pct,0)}%",'CellR')])
story += [table(rows,[12*mm,47*mm,39*mm,39*mm,29*mm]),Spacer(1,5),P('Eight of the ten selected batters appear in the top ten in all 15 scenarios. Hardik Pandya appears in 14 of 15 scenarios (93%); Marcus Stoinis appears in 12 of 15 (80%). The latter is the most scenario-sensitive batting selection at the cutoff.'),P('The batting evidence table in the project package contains each selected player’s pressure and normal-context output, dismissal-risk estimate, consistency component, role coverage, evidence tier and knockout diagnostic.'),PageBreak()]
# Bowling and validation
story += [P('10. Final bowler rankings','H1R'),P('Death wicket rate is expressed as bowler-credited wickets per 100 legal death balls. The table reports wickets and legal balls separately.' ,'SmallR')]
rows=[[P('Rank','HeadR'),P('Player','HeadR'),P('Style','HeadR'),P('IPL wickets<br/>(legal balls)','HeadR'),P('T20I wickets<br/>(legal balls)','HeadR'),P('Top-ten stability','HeadR')]]
for _,r in bowl.iterrows():
 rows.append([P(int(r.final_rank),'CellR'),P(r.bowler_canonical_name,'CellR'),P(r.IPL_pace_spin_role,'CellR'),P(f"{I(r.IPL_death_wickets)} ({I(r.IPL_death_legal_balls)})",'CellR'),P(f"{I(r.T20I_death_wickets)} ({I(r.T20I_death_legal_balls)})",'CellR'),P(f"{N(r.top10_robustness_pct,0)}%",'CellR')])
story += [table(rows,[11*mm,39*mm,19*mm,34*mm,34*mm,28*mm]),Spacer(1,5),P('Jason Behrendorff, Yuzvendra Chahal and Corbin Bosch remain in the top ten in all nine scenarios. Jamie Overton, Spencer Johnson, Tim Southee and Umran Malik remain in the top ten in eight of nine scenarios.'),P('Joshua Little’s evidence is format-asymmetric: 17 T20I death wickets from 128 legal balls, compared with none from 54 IPL death balls. Adam Zampa appears in three of nine scenarios (33%); his IPL death-ball exposure is at the 36-ball eligibility threshold. These limitations are relevant when interpreting the lower positions.'),P('11. Interactive system','H1R'),P('The accompanying web application presents the same prepared evidence in four main working areas:'),P('<b>Rankings:</b> the Batting Index and Bowling Index show the final combined lists. The format controls switch to the eligible IPL-only or T20I-only comparison; these are format-specific rankings and should not be confused with the combined final list.'),P('<b>Player profiles:</b> search the player pool to inspect format records, pressure exposure, component scores and evidence support. The profile view is intended to explain why a player ranks where they do, rather than display only a final number.'),P('<b>Scenario testing:</b> choose batting or bowling, select a ranking scope and format blend, adjust component weights, and recalculate. The output is a user-defined scenario based on precomputed role-normalised component scores. It does not modify the official final ranking.'),P('<b>Methodology:</b> the dashboard includes a concise description of the pressure definition, formulas, thresholds and limitations. The PDF is the full written explanation.'),P('The application uses static, prepared JSON data for the rankings and player records, with a small API layer for scenario calculations. This keeps the public dashboard responsive and avoids rerunning the full delivery-level research pipeline on every interaction.'),P('12. Validation','H1R'),P('The project checks player-format key uniqueness, score bounds, pressure and death-phase exposure, and reconciliation of death-phase legal balls and bowler-credited wickets against the reliability evidence. The final scope-specific scorecards contain no duplicate player-format keys. Composite score bounds are 0 to 100. All-death legal-ball and credited-wicket reconciliation differences are zero.'),P('The final lists contain ten unique batters and ten unique bowlers. Each selected player meets the minimum evidence rules in both formats. Scenario counts are 15 for batting and nine for bowling.'),PageBreak()]
# Limitations
story += [P('13. Limitations','H1R'),P('<b>Pressure definition.</b> The model uses innings progress and wickets already lost. It does not reconstruct exact required run rate, score margin or match closeness because the source fields do not consistently support reliable calculation of those variables.'),P('<b>Bowling control.</b> Known boundary events are an incomplete proxy. The model does not claim to calculate official bowling economy, total runs conceded or a complete dot-ball rate.'),P('<b>Knockout evidence.</b> Knockout observations are retained as diagnostics, but the number of qualifying deliveries is too limited for a stable, like-for-like component in the final ranking.'),P('<b>Percentile scores.</b> Percentiles are relative positions among observed peers in the analysed sample. They are not probabilities, causal effects or forecasts of future performance.'),P('<b>Cross-format eligibility.</b> The final combined lists include only players who qualify in both IPL and T20I. This supports a common comparison basis but excludes players with strong evidence in only one format.'),P('<b>Historical coverage.</b> Results reflect the seasons and matches available in the supplied dataset. They are not a complete assessment of a player’s career or current ability.'),P('14. Summary','H1R'),P('The final rankings are based on an explicit pre-delivery pressure definition, separate batting and bowling models, format- and role/style-adjusted peer comparisons, minimum sample requirements, match-level consistency measures and scenario testing. The report and dashboard retain format-specific exposure and component evidence so that the final order can be reviewed against the underlying observations.'),P('The batting top ten is more stable across the tested scenarios than the bowling top ten. The final bowling positions are more sensitive to weighting and format blending, and the report identifies the relevant sample limitations. The rankings should be interpreted together with the evidence counts and stability figures.'),Spacer(1,8),HRFlowable(width='100%',thickness=.6,color=colors.HexColor('#777777'),spaceBefore=4,spaceAfter=7),P('SupeRR Selector Season 2 · Round 1 · Prepared by Faaiz Qureshi','CaptionR')]

def footer(c,doc):
 c.saveState(); w,h=A4
 if doc.page>1:
  c.setFont('ReportSans',7); c.setFillColor(colors.HexColor('#555555')); c.drawString(19*mm,h-12*mm,'SUPERR SELECTOR SEASON 2  /  METHODOLOGY REPORT')
  c.setStrokeColor(colors.HexColor('#999999')); c.setLineWidth(.35); c.line(19*mm,h-15*mm,w-19*mm,h-15*mm)
 c.setStrokeColor(colors.HexColor('#999999')); c.setLineWidth(.35); c.line(19*mm,14*mm,w-19*mm,14*mm)
 c.setFont('ReportSans',7); c.setFillColor(colors.HexColor('#555555')); c.drawString(19*mm,9*mm,'Faaiz Qureshi  |  17 November 2026'); c.drawRightString(w-19*mm,9*mm,str(doc.page)); c.restoreState()

doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=19*mm,leftMargin=19*mm,topMargin=22*mm,bottomMargin=21*mm,title='SupeRR Selector Season 2 - Methodology Report',author='Faaiz Qureshi',subject='Round 1 pressure performance analysis')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)
